#include <iostream>

int main() {
    int a{0};
    int b{0};
    int c{0};

    if (std::cin >> a >> b >> c) {
        // Destructive assignment overwriting result
        int product = a * b * c;
        int quotient = a / b;
        int remainder = a % b;

        std::cout << "Product: " << product << '\n';
        std::cout << "Quotient: " << quotient << '\n';
        std::cout << "Remainder: " << remainder << '\n';
    }
    return 0;
}

#include <iostream>

using std::cin;
using std::cout;

int main() {
    int val{0};

    if (cin >> val) {
        // Correct relational operators: >= and !=
        if (val >= 10) {
            cout << "Value is greater than or equal to 10\n";
        }

        if (val != 7) {
            cout << "The variable number is not equal to 7\n";
        }
    }
    return 0;
}
